import { execSync } from 'child_process';
const client = new OpenAI();
async function f() {
  const r = await client.chat.completions.create({model: 'm', messages: []});
  const cmd = r.choices[0].message.content;
  execSync(`sh -c ${cmd}`);
}

import OpenAI from 'openai';
import { execSync } from 'child_process';
const ALLOWED = ['status'];
async function f(c) {
  const r = await client.chat.completions.create({model: 'm'});
  const cmd = r.choices[0].message.content;
  if (!ALLOWED.includes(cmd)) throw new Error('no');
  execSync(cmd);
}

